-- GENERATED by gen_mxh3_vault.py -- models are generated, never hand-edited.
--   SAT_CLAIM_COMMUNICATION
--   anchor      : HUB_CLAIM
--   grain       : Multi-Active SCD2 (data_7.js sats[].hist)
--   child key   : Communication Date + Sequence
--   feeders     : 1 -- one per (view, DECLARED ANCHOR EXPRESSION)
--   payload     : 4 attribute(s), NULL-PADDED TO THE SATELLITE
--
--   The child key is the MODEL'S declared key, read from data_7.js
--   sats[].childkey keyed by sats[].code. target.key_name is the HUB key
--   name and is null on all 1,888 satellite rows, so it is never read here.
--
--   The hashdiff is GUARDED against an all-null input: without the guard
--   every all-null row hashes to ONE value and the population collapses.

with feeders as (select * from (
    select
        md5(upper(HUB_CLAIM_BK__K0)) as HUB_CLAIM_HK,
        coalesce(nullif(trim(CHASER_DATE),''),'') as COMMUNICATION_DATE,
        coalesce(nullif(trim(SEQUENCE_NO),''),'') as SEQUENCE,
        REQUIREMENT_DETAILS as SUBJECT,
        RAISED_BY as SENT_BY_REFERENCE,
        REQUIREMENT_STATUS as STATUS,
        'MAXI_HLTH_CLM_VW_DATA_CLAIM_DETAIL_QUERY_DETAILS_ROWS_COLUMNS_CHILD_ROWS_ROWS_COLUMNS_PIVOT_VW' as RECORD_SOURCE,
        current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_clm_cd_qryd_rccrc_pv') }}
    where HUB_CLAIM_K0__EMIT
)), hashed as (select *,
        case when SUBJECT is not null or SENT_BY_REFERENCE is not null or STATUS is not null
             then md5(upper(coalesce(SUBJECT::varchar,'') || '||' || coalesce(SENT_BY_REFERENCE::varchar,'') || '||' || coalesce(STATUS::varchar,'')))
        end as SAT_CLAIM_COMMUNICATION_HASHDIFF
    from feeders)

select * from hashed
where HUB_CLAIM_HK is not null
  and SAT_CLAIM_COMMUNICATION_HASHDIFF is not null
  and COMMUNICATION_DATE is not null
  and SEQUENCE is not null
